INSERT INTO reviews (id, user_id, product_id, rating, comment, created_at, updated_at) VALUES
(1, 2, 3, 5, 'Battery backup is reliable and the display looks premium for the price.', '2026-03-29 09:00:00', '2026-03-29 09:00:00'),
(2, 3, 41, 5, 'Great for home workouts and saves space compared to fixed dumbbells.', '2026-03-30 12:10:00', '2026-03-30 12:10:00'),
(3, 4, 12, 4, 'Nice fit and good quality denim. Slightly heavier than expected.', '2026-03-31 17:20:00', '2026-03-31 17:20:00'),
(4, 5, 33, 4, 'Warm lighting and simple controls. Looks good on my study table.', '2026-03-25 11:40:00', '2026-03-25 11:40:00'),
(5, 6, 6, 5, 'Smooth performance for streaming and online classes. Worth the price.', '2026-03-31 08:55:00', '2026-03-31 08:55:00'),
(6, 7, 24, 5, 'Easy to read and genuinely motivating. A good repeat-read book.', '2026-03-28 19:00:00', '2026-03-28 19:00:00'),
(7, 8, 27, 4, 'Good beginner guide for web development with simple explanations.', '2026-03-27 16:30:00', '2026-03-27 16:30:00'),
(8, 9, 44, 5, 'Comfortable straps and enough compartments for a weekend trek.', '2026-04-01 08:10:00', '2026-04-01 08:10:00'),
(9, 10, 18, 4, 'Comfortable stretch and fits well for daily wear and yoga.', '2026-03-30 14:25:00', '2026-03-30 14:25:00'),
(10, 11, 32, 5, 'Keeps water cold for hours and feels sturdy enough for travel.', '2026-03-29 07:45:00', '2026-03-29 07:45:00');
